import { Agent, getAgentByName, routeAgentRequest } from 'agents';

export class Chat extends Agent {
  async onMessage(connection, message) {
    connection.send(`echo: ${message}`);
  }
}

export class Report extends Agent {
  initialState = { report: null };
  async generate(topic) {
    const report = `Report on ${topic}`;
    this.setState({ report });
    return report;
  }
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (request.method === 'POST' && url.pathname === '/reports') {
      const { topic } = await request.json();
      const id = crypto.randomUUID();
      const report = await (await getAgentByName(env.Report, id)).generate(topic);
      return Response.json({ id, report });
    }
    return (await routeAgentRequest(request, env)) ?? new Response('Not found', { status: 404 });
  },
};

